// Arithmetic series sum: 1 + 2 + ... + n (with 0 -> 0).
// Assumption from the problem statement: the result is strictly < 10_000,
// so it safely fits in u64 and cannot overflow.

pub fn compute_arith_sum(n: u64) -> u64 {
    let mut sum: u64 = 0;
    let mut i: u64 = 0;

    // Invariant (informal):
    // - 0 <= i <= n
    // - sum == 1 + 2 + ... + i
    // - sum <= 1 + 2 + ... + n < 10_000
    while i < n {
        i += 1;
        sum += i;
    }

    sum
}